INSERT INTO `Jutsu` (`id`, `name`, `description`, `effects`, `target`, `range`, `cooldown`, `requiredLevel`, `requiredRank`, `jutsuType`, `image`, `statClassification`, `elementClassification`, `battleDescription`, `jutsuRank`, `actionCostPerc`, `staminaCost`, `chakraCost`, `method`, `hidden`) VALUES
  ('creator-trial-hotfix-jab', 'Hotfix Jab', 'A short, ugly jab pushed straight to production. It was not tested, but it does land.', '[{"staticAssetPath":"","staticAnimation":"","appearAnimation":"wwrpz2v69a2pJZNN2abAD","disappearAnimation":"","appearSfx":"yGzPWg1cLQc6dYd1EpCsl","disappearSfx":"","rounds":0,"power":45,"powerPerLevel":0,"direction":"offence","target":"INHERIT","calculation":"formula","statTypes":["Taijutsu"],"generalTypes":["Strength","Speed"],"elements":[],"type":"damage","description":"Deals damage to target","residualModifier":0,"dmgModifier":1,"allowBloodlineDamageIncrease":true,"allowBloodlineDamageDecrease":true}]', 'OTHER_USER', 1, 0, 1, 'STUDENT', 'AI', 'https://uploadthing.b-cdn.net/f/Hzww9EQvYURJdL7jc3P62PI3ciLaYzgVX8FopBADxSrGmvQl', 'Taijutsu', 'None', '%user mutters something about shipping on a Friday and snaps a chrome fist into %target.', 'D', 60, 0, 0, 'SINGLE', 1),
  ('creator-trial-spare-parts-toss', 'Spare Parts Toss', 'A handful of loose gears and rivets thrown hard enough to matter.', '[{"staticAssetPath":"","staticAnimation":"","appearAnimation":"Yhgv_oX9rdlceqaFboAIF","disappearAnimation":"","appearSfx":"yGzPWg1cLQc6dYd1EpCsl","disappearSfx":"","rounds":0,"power":50,"powerPerLevel":0,"direction":"offence","target":"INHERIT","calculation":"formula","statTypes":["Bukijutsu"],"generalTypes":["Strength","Speed"],"elements":[],"type":"damage","description":"Deals damage to target","residualModifier":0,"dmgModifier":1,"allowBloodlineDamageIncrease":true,"allowBloodlineDamageDecrease":true}]', 'OTHER_USER', 4, 2, 1, 'STUDENT', 'AI', 'https://uploadthing.b-cdn.net/f/Hzww9EQvYURJZOYgV7naYQrBIUTu69nkMxWmS4ah0O7LVCp8', 'Bukijutsu', 'None', '%user digs through a jacket pocket and hurls a fistful of gears and rivets at %target.', 'D', 60, 0, 0, 'SINGLE', 1),
  ('creator-trial-emergency-reboot', 'Emergency Reboot', 'A forced restart that patches the worst of the damage.', '[{"staticAssetPath":"","staticAnimation":"","appearAnimation":"Ceo4dEys-92Mj70YCbHzw","disappearAnimation":"","appearSfx":"4iG_WpgEmPGUzHn8z129r","disappearSfx":"","rounds":0,"power":20,"powerPerLevel":0,"direction":"offence","target":"SELF","calculation":"percentage","poolsAffected":["Health"],"type":"heal","description":"Heals themselves or others"}]', 'SELF', 0, 6, 1, 'STUDENT', 'AI', 'https://uploadthing.b-cdn.net/f/Hzww9EQvYURJP9cgGPpKeUGyX2kj6u45AOQiSa1zYH0mqZoc', 'None', 'None', '%user''s eyes flicker off and back on as a forced restart seals the worst of the damage.', 'D', 40, 0, 0, 'SINGLE', 1),
  ('creator-trial-servo-blade-flurry', 'Servo Blade Flurry', 'A blur of slashes from a forearm-mounted blade driven by overclocked servos.', '[{"staticAssetPath":"","staticAnimation":"","appearAnimation":"4fHEJ76HpyeAa_2Jda0oz","disappearAnimation":"","appearSfx":"vJNaizZBpHEKyccPE1wem","disappearSfx":"","rounds":0,"power":58,"powerPerLevel":0,"direction":"offence","target":"INHERIT","calculation":"formula","statTypes":["Taijutsu"],"generalTypes":["Strength","Speed"],"elements":["Metal"],"type":"damage","description":"Deals damage to target","residualModifier":0,"dmgModifier":1,"allowBloodlineDamageIncrease":true,"allowBloodlineDamageDecrease":true}]', 'OTHER_USER', 1, 1, 1, 'GENIN', 'AI', 'https://uploadthing.b-cdn.net/f/Hzww9EQvYURJy2Q31JZukVH2MI5Lo4ehEfAXvZdcmtWqPg7r', 'Taijutsu', 'Metal', 'Servos scream as %user carves into %target with a blur of forearm-blade slashes.', 'C', 60, 0, 0, 'SINGLE', 1),
  ('creator-trial-arc-rivet', 'Arc Rivet', 'A superheated rivet fired on a rail of lightning. It locks up whoever it strikes.', '[{"staticAssetPath":"","staticAnimation":"","appearAnimation":"uuO5UGNydeYmx3_tWRZrH","disappearAnimation":"","appearSfx":"kEtVeccUUea888kBAMLiR","disappearSfx":"","rounds":0,"power":52,"powerPerLevel":0,"direction":"offence","target":"INHERIT","calculation":"formula","statTypes":["Ninjutsu"],"generalTypes":["Intelligence","Willpower"],"elements":["Lightning"],"type":"damage","description":"Deals damage to target","residualModifier":0,"dmgModifier":1,"allowBloodlineDamageIncrease":true,"allowBloodlineDamageDecrease":true},{"staticAssetPath":"","staticAnimation":"","appearAnimation":"0JTR_qZKVuFL9kW5HKHYh","disappearAnimation":"","appearSfx":"kEtVeccUUea888kBAMLiR","disappearSfx":"","rounds":1,"power":35,"powerPerLevel":0,"direction":"offence","target":"INHERIT","calculation":"static","type":"stun","description":"Stuns the target","apReduction":30}]', 'OTHER_USER', 5, 3, 1, 'GENIN', 'AI', 'https://uploadthing.b-cdn.net/f/Hzww9EQvYURJ2BiHRznMXlcRpYmJ5do0zKw4Qx6PVEtBa9b8', 'Ninjutsu', 'Lightning', '%user fires a rivet down a rail of cyan lightning, and it bursts against %target in a crackling arc.', 'C', 60, 0, 0, 'SINGLE', 1),
  ('creator-trial-cyan-overclock', 'Cyan Overclock', 'Removes the safety limiters on every servo in the frame for a short time.', '[{"staticAssetPath":"","staticAnimation":"","appearAnimation":"jqwh2NBOMajt7sCz8qgWc","disappearAnimation":"","appearSfx":"kEtVeccUUea888kBAMLiR","disappearSfx":"","rounds":3,"power":25,"powerPerLevel":0,"direction":"offence","target":"SELF","calculation":"percentage","type":"increasedamagegiven","description":"Increase damage given by target"}]', 'SELF', 0, 6, 1, 'GENIN', 'AI', 'https://uploadthing.b-cdn.net/f/Hzww9EQvYURJyda5nlukVH2MI5Lo4ehEfAXvZdcmtWqPg7rp', 'None', 'Lightning', 'Safety limiters click off one by one as cyan current floods through the limbs of %user.', 'C', 40, 0, 0, 'SINGLE', 1),
  ('creator-trial-violet-edge-crescent', 'Violet Edge Crescent', 'A wide cut from a plasma-edged katana that burns through everything along its arc.', '[{"staticAssetPath":"","staticAnimation":"","appearAnimation":"z6F0aNUJXZcs0_M2iW-aR","disappearAnimation":"","appearSfx":"vJNaizZBpHEKyccPE1wem","disappearSfx":"","rounds":0,"power":62,"powerPerLevel":0,"direction":"offence","target":"INHERIT","calculation":"formula","statTypes":["Bukijutsu"],"generalTypes":["Strength","Speed"],"elements":["Metal"],"type":"damage","description":"Deals damage to target","residualModifier":0,"dmgModifier":1,"allowBloodlineDamageIncrease":true,"allowBloodlineDamageDecrease":true}]', 'GROUND', 2, 2, 1, 'CHUNIN', 'AI', 'https://uploadthing.b-cdn.net/f/Hzww9EQvYURJvM3kHqEmSnXwslYEpV1yOeNL8gMtqhjPdf36', 'Bukijutsu', 'Metal', '%user sweeps the plasma katana in a wide violet crescent that burns through everything along its arc.', 'B', 60, 0, 0, 'AOE_WALL_SHOOT', 1),
  ('creator-trial-magnetic-lockdown', 'Magnetic Lockdown', 'A focused magnetic field that drags at every piece of metal on the target.', '[{"staticAssetPath":"","staticAnimation":"","appearAnimation":"W0Hyv7gQYulBc2hCE148Y","disappearAnimation":"","appearSfx":"kEtVeccUUea888kBAMLiR","disappearSfx":"","rounds":0,"power":40,"powerPerLevel":0,"direction":"offence","target":"INHERIT","calculation":"formula","statTypes":["Ninjutsu"],"generalTypes":["Intelligence","Willpower"],"elements":["Magnet"],"type":"damage","description":"Deals damage to target","residualModifier":0,"dmgModifier":1,"allowBloodlineDamageIncrease":true,"allowBloodlineDamageDecrease":true},{"staticAssetPath":"","staticAnimation":"","appearAnimation":"F48r3hjQLRcDnANb6qVeb","disappearAnimation":"","appearSfx":"kEtVeccUUea888kBAMLiR","disappearSfx":"","rounds":1,"power":55,"powerPerLevel":0,"direction":"offence","target":"INHERIT","calculation":"static","type":"stun","description":"Stuns the target","apReduction":30}]', 'OTHER_USER', 4, 5, 1, 'CHUNIN', 'AI', 'https://uploadthing.b-cdn.net/f/Hzww9EQvYURJQQ1OanjhzBPya1rwfCIqOTU0cV5xgsMeo3u2', 'Ninjutsu', 'Magnet', '%user levels the katana at %target, and a magnetic field wrenches every piece of metal they carry into a violent lock.', 'B', 60, 0, 0, 'SINGLE', 1),
  ('creator-trial-flak-protocol', 'Flak Protocol', 'Interlocks every armour plate on the frame to soak incoming blows.', '[{"staticAssetPath":"","staticAnimation":"","appearAnimation":"8qaWucWHQOrRK8GYAvWyl","disappearAnimation":"","appearSfx":"mOSkDnYv4hchkPbhdpTDd","disappearSfx":"","rounds":3,"power":35,"powerPerLevel":0,"direction":"offence","target":"SELF","calculation":"percentage","type":"decreasedamagetaken","description":"Decrease damage taken of target"}]', 'SELF', 0, 6, 1, 'CHUNIN', 'AI', 'https://uploadthing.b-cdn.net/f/Hzww9EQvYURJ0orUT0grYldRWJcD6vE10SjNsXHeA9pVMfQi', 'None', 'None', 'Armour plates slam together across the frame of %user, sealing every seam in a hard violet glow.', 'B', 40, 0, 0, 'SINGLE', 1),
  ('creator-trial-plasma-discharge', 'Plasma Discharge', 'Vents the plasma reservoir onto the ground in one violent burst.', '[{"staticAssetPath":"","staticAnimation":"","appearAnimation":"vWw8rBufuOquHg6onFFTI","disappearAnimation":"","appearSfx":"yGzPWg1cLQc6dYd1EpCsl","disappearSfx":"","rounds":0,"power":60,"powerPerLevel":0,"direction":"offence","target":"INHERIT","calculation":"formula","statTypes":["Ninjutsu"],"generalTypes":["Intelligence","Willpower"],"elements":["Lightning"],"type":"damage","description":"Deals damage to target","residualModifier":0,"dmgModifier":1,"allowBloodlineDamageIncrease":true,"allowBloodlineDamageDecrease":true}]', 'GROUND', 3, 4, 1, 'CHUNIN', 'AI', 'https://uploadthing.b-cdn.net/f/Hzww9EQvYURJzDc4dIemvaQu94EYJs8HpxVzofny6iPtbgCZ', 'Ninjutsu', 'Lightning', 'Vents across %user slam open and dump a crackling burst of violet plasma onto the battlefield.', 'B', 60, 0, 0, 'AOE_CIRCLE_SPAWN', 1),
  ('creator-trial-rotary-barrage', 'Rotary Barrage', 'A long tearing burst from the arm-mounted rotary cannon, raking everything in its line.', '[{"staticAssetPath":"","staticAnimation":"","appearAnimation":"2FzLhSmuR_AJC2KVQh1Ih","disappearAnimation":"","appearSfx":"vJNaizZBpHEKyccPE1wem","disappearSfx":"","rounds":0,"power":72,"powerPerLevel":0,"direction":"offence","target":"INHERIT","calculation":"formula","statTypes":["Bukijutsu"],"generalTypes":["Strength","Speed"],"elements":["Metal"],"type":"damage","description":"Deals damage to target","residualModifier":0,"dmgModifier":1,"allowBloodlineDamageIncrease":true,"allowBloodlineDamageDecrease":true}]', 'GROUND', 5, 2, 1, 'JONIN', 'AI', 'https://uploadthing.b-cdn.net/f/Hzww9EQvYURJX3gEsMqIOpAoLKbZ4nW9Rsil2V67yuFwQhqv', 'Bukijutsu', 'Metal', 'The rotary cannon on %user spins up with a rising howl and rakes a long line of the battlefield with tracer fire.', 'A', 60, 0, 0, 'AOE_LINE_SHOOT', 1),
  ('creator-trial-rocket-salvo', 'Rocket Salvo', 'Empties both shoulder pods onto a marked area of the battlefield.', '[{"staticAssetPath":"","staticAnimation":"","appearAnimation":"4nNyh2K7VmBUzNNu85wkM","disappearAnimation":"","appearSfx":"vJNaizZBpHEKyccPE1wem","disappearSfx":"","rounds":0,"power":78,"powerPerLevel":0,"direction":"offence","target":"INHERIT","calculation":"formula","statTypes":["Ninjutsu"],"generalTypes":["Intelligence","Willpower"],"elements":["Explosion"],"type":"damage","description":"Deals damage to target","residualModifier":0,"dmgModifier":1,"allowBloodlineDamageIncrease":true,"allowBloodlineDamageDecrease":true}]', 'GROUND', 4, 4, 1, 'JONIN', 'AI', 'https://uploadthing.b-cdn.net/f/Hzww9EQvYURJjrxFm6W4XzPI8f1v96qBot0Q3wsUp2nxu7SM', 'Ninjutsu', 'Explosion', 'Both shoulder pods of %user open and a salvo of rockets arcs up and comes down in a storm of fire.', 'A', 60, 0, 0, 'AOE_CIRCLE_SPAWN', 1),
  ('creator-trial-siege-claw', 'Siege Claw', 'A wall-breaking swipe from a gauntlet built to tear open fortresses.', '[{"staticAssetPath":"","staticAnimation":"","appearAnimation":"2FzLhSmuR_AJC2KVQh1Ih","disappearAnimation":"","appearSfx":"yGzPWg1cLQc6dYd1EpCsl","disappearSfx":"","rounds":0,"power":90,"powerPerLevel":0,"direction":"offence","target":"INHERIT","calculation":"formula","statTypes":["Taijutsu"],"generalTypes":["Strength","Speed"],"elements":["Metal"],"type":"damage","description":"Deals damage to target","residualModifier":0,"dmgModifier":1,"allowBloodlineDamageIncrease":true,"allowBloodlineDamageDecrease":true}]', 'OTHER_USER', 1, 3, 1, 'JONIN', 'AI', 'https://uploadthing.b-cdn.net/f/Hzww9EQvYURJvcAIhiEmSnXwslYEpV1yOeNL8gMtqhjPdf36', 'Taijutsu', 'Metal', '%user drags a gauntlet built for fortress walls straight through %target.', 'A', 60, 0, 0, 'SINGLE', 1),
  ('creator-trial-reactor-vent', 'Reactor Vent', 'Vents the chest reactor to repair the hull and push every system beyond its rating.', '[{"staticAssetPath":"","staticAnimation":"","appearAnimation":"fsFt9OCaksDuJY42C60VY","disappearAnimation":"","appearSfx":"4iG_WpgEmPGUzHn8z129r","disappearSfx":"","rounds":0,"power":15,"powerPerLevel":0,"direction":"offence","target":"SELF","calculation":"percentage","poolsAffected":["Health"],"type":"heal","description":"Heals themselves or others"},{"staticAssetPath":"","staticAnimation":"","appearAnimation":"X2jyvcUE3LQno6lDv-PO2","disappearAnimation":"","appearSfx":"kEtVeccUUea888kBAMLiR","disappearSfx":"","rounds":3,"power":30,"powerPerLevel":0,"direction":"offence","target":"SELF","calculation":"percentage","type":"increasedamagegiven","description":"Increase damage given by target"}]', 'SELF', 0, 6, 1, 'JONIN', 'AI', 'https://uploadthing.b-cdn.net/f/Hzww9EQvYURJtxxQcRhUYJDfpFXWm3nrcPluEtIZqyLkaSV1', 'None', 'Fire', 'The chest reactor of %user flares white-orange as it vents, welding the hull shut and pushing every system past its rating.', 'A', 40, 0, 0, 'SINGLE', 1),
  ('creator-trial-judgment-cleave', 'Judgment Cleave', 'A cut from a blade the size of a watchtower. The ground does not recover from it.', '[{"staticAssetPath":"","staticAnimation":"","appearAnimation":"UsluMNJwRVXuZTQEnYsIt","disappearAnimation":"","appearSfx":"vJNaizZBpHEKyccPE1wem","disappearSfx":"","rounds":0,"power":100,"powerPerLevel":0,"direction":"offence","target":"INHERIT","calculation":"formula","statTypes":["Bukijutsu"],"generalTypes":["Strength","Speed"],"elements":["Light"],"type":"damage","description":"Deals damage to target","residualModifier":0,"dmgModifier":1,"allowBloodlineDamageIncrease":true,"allowBloodlineDamageDecrease":true}]', 'GROUND', 3, 3, 1, 'ELITE JONIN', 'AI', 'https://uploadthing.b-cdn.net/f/Hzww9EQvYURJ3rUQY78pYHJX5rdkUTfOKtvu2eGIELmSWqBx', 'Bukijutsu', 'Light', '%user raises a blade the size of a watchtower and brings it down in a wall of white and crimson light.', 'S', 60, 0, 0, 'AOE_LARGE_WALL_SHOOT', 1),
  ('creator-trial-orbital-verdict', 'Orbital Verdict', 'Calls a pillar of light down on a chosen area of the battlefield. Survivors stagger.', '[{"staticAssetPath":"","staticAnimation":"","appearAnimation":"_LXkKSw5-ojoJmLSumeyC","disappearAnimation":"","appearSfx":"yGzPWg1cLQc6dYd1EpCsl","disappearSfx":"","rounds":0,"power":92,"powerPerLevel":0,"direction":"offence","target":"INHERIT","calculation":"formula","statTypes":["Ninjutsu"],"generalTypes":["Intelligence","Willpower"],"elements":["Light"],"type":"damage","description":"Deals damage to target","residualModifier":0,"dmgModifier":1,"allowBloodlineDamageIncrease":true,"allowBloodlineDamageDecrease":true},{"staticAssetPath":"","staticAnimation":"","appearAnimation":"aQzJPhLB8zQh2xhrH89GD","disappearAnimation":"","appearSfx":"kEtVeccUUea888kBAMLiR","disappearSfx":"","rounds":1,"power":45,"powerPerLevel":0,"direction":"offence","target":"INHERIT","calculation":"static","type":"stun","description":"Stuns the target","apReduction":30}]', 'GROUND', 5, 5, 1, 'ELITE JONIN', 'AI', 'https://uploadthing.b-cdn.net/f/Hzww9EQvYURJjrNPJJj4XzPI8f1v96qBot0Q3wsUp2nxu7SM', 'Ninjutsu', 'Light', 'The halo of %user tilts, and a pillar of golden light falls from the sky onto the chosen ground.', 'S', 80, 0, 0, 'AOE_CIRCLE_SPAWN', 1),
  ('creator-trial-kernel-panic', 'Kernel Panic', 'An illegal instruction fired straight into the nervous system. Everything stops working as it should.', '[{"staticAssetPath":"","staticAnimation":"","appearAnimation":"tOjpRrxDqMR9WmahwlDTG","disappearAnimation":"","appearSfx":"kEtVeccUUea888kBAMLiR","disappearSfx":"","rounds":0,"power":70,"powerPerLevel":0,"direction":"offence","target":"INHERIT","calculation":"formula","statTypes":["Genjutsu"],"generalTypes":["Intelligence","Willpower"],"elements":[],"type":"damage","description":"Deals damage to target","residualModifier":0,"dmgModifier":1,"allowBloodlineDamageIncrease":true,"allowBloodlineDamageDecrease":true},{"staticAssetPath":"","staticAnimation":"","appearAnimation":"KWocE90rzQ4mInp3WK4g2","disappearAnimation":"","appearSfx":"kEtVeccUUea888kBAMLiR","disappearSfx":"","rounds":3,"power":30,"powerPerLevel":0,"direction":"offence","target":"INHERIT","calculation":"percentage","type":"decreasedamagegiven","description":"Decrease damage given by target"}]', 'OTHER_USER', 5, 5, 1, 'ELITE JONIN', 'AI', 'https://uploadthing.b-cdn.net/f/Hzww9EQvYURJcvUeqUSnxBpQqGNDcTHbLmYz8uXAl3oa54ti', 'Genjutsu', 'None', '%user points one finger at %target and pushes an illegal instruction straight into their nervous system.', 'S', 60, 0, 0, 'SINGLE', 1),
  ('creator-trial-halo-bastion', 'Halo Bastion', 'Folds the blade wings into a shell of hard gold light and mends the armour beneath it.', '[{"staticAssetPath":"","staticAnimation":"","appearAnimation":"AO5aZLgBsgIMMr9oh5YG0","disappearAnimation":"","appearSfx":"mOSkDnYv4hchkPbhdpTDd","disappearSfx":"","rounds":2,"power":50,"powerPerLevel":0,"direction":"offence","target":"SELF","calculation":"percentage","type":"decreasedamagetaken","description":"Decrease damage taken of target"},{"staticAssetPath":"","staticAnimation":"","appearAnimation":"lFlZ7dqGCOI-H8TgqPGlK","disappearAnimation":"","appearSfx":"4iG_WpgEmPGUzHn8z129r","disappearSfx":"","rounds":0,"power":10,"powerPerLevel":0,"direction":"offence","target":"SELF","calculation":"percentage","poolsAffected":["Health"],"type":"heal","description":"Heals themselves or others"}]', 'SELF', 0, 6, 1, 'ELITE JONIN', 'AI', 'https://uploadthing.b-cdn.net/f/Hzww9EQvYURJlaqsC0rWYxAsuC7ofQn9pM45OD0ERqkdBXJU', 'None', 'Light', 'Six blade wings fold around %user into a shell of hard gold light, and the armour beneath it knits back together.', 'S', 40, 0, 0, 'SINGLE', 1),
  ('creator-trial-star-core-ascension', 'Star Core Ascension', 'Unbinds the star reactor. For a moment the machine stops being a machine.', '[{"staticAssetPath":"","staticAnimation":"","appearAnimation":"inDRcdvSKDEPz2VaQPS0x","disappearAnimation":"","appearSfx":"kEtVeccUUea888kBAMLiR","disappearSfx":"","rounds":3,"power":45,"powerPerLevel":0,"direction":"offence","target":"SELF","calculation":"percentage","type":"increasedamagegiven","description":"Increase damage given by target"}]', 'SELF', 0, 8, 1, 'ELITE JONIN', 'AI', 'https://uploadthing.b-cdn.net/f/Hzww9EQvYURJ7ddpU4mXKPBOUWGyFuM4DlL1v5HNTZhkte0z', 'None', 'Light', 'The star reactor of %user burns white, and for a moment the air around it stops behaving like air.', 'S', 40, 0, 0, 'SINGLE', 1)
